273	      }
274	      occurredAt = body.occurredAt;
275	    }
276	
277	    const event = {
278	      id: randomUUID(),
279	      type: body.type,
280	      payload: body.payload ?? {},
281	      occurredAt,
282	      sequence: scenario.events.length + 1
283	    };
284	    scenario.events.push(event);
285	    scenario.revision += 1;
