312	      badRequest(response, "currentTime must not be earlier than the last event's occurredAt");
313	      return;
314	    }
315	    const existing = store.clocks.get(id);
316	    if (existing !== undefined && parsed.getTime() < Date.parse(existing)) {
317	      badRequest(response, "currentTime must not be earlier than the current clock time");
318	      return;
