342	  function listEvents(response, id, url) {
343	    const scenario = store.scenarios.get(id);
344	    if (!scenario) {
345	      notFound(response, "Scenario not found");
346	      return;
347	    }
348	
349	    const paramKeys = new Set(url.searchParams.keys());
350	    for (const key of paramKeys) {
351	      if (!EVENT_QUERY_PARAMS.has(key)) {
352	        badRequest(response, `Unknown query parameter: ${key}`);
353	        return;
354	      }
355	    }
356	
357	    let fromIso = null;
358	    let toIso = null;
359	    let limit = DEFAULT_EVENTS_LIMIT;
360	    let cursorToken = undefined;
361	
362	    for (const name of ["from", "to", "limit", "cursor"]) {
363	      const result = readSingleParam(url, name);
364	      if (result.error) {
365	        badRequest(response, result.error);
366	        return;
367	      }
368	      const raw = result.value;
369	      if (raw === undefined) {
370	        continue;
371	      }
372	      if (raw === "") {
373	        badRequest(response, `${name} must not be empty`);
374	        return;
375	      }
376	      if (name === "from" || name === "to") {
377	        const date = parseUtcTimestamp(raw);
378	        if (date === null) {
379	          badRequest(response, `${name} must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ`);
380	          return;
381	        }
382	        if (name === "from") {
383	          fromIso = raw;
384	        } else {
385	          toIso = raw;
386	        }
387	      } else if (name === "limit") {
388	        if (!DECIMAL_INTEGER_PATTERN.test(raw) || raw.length > 9) {
389	          badRequest(response, "limit must be a decimal integer between 1 and 100");
390	          return;
391	        }
392	        limit = Number(raw);
393	        if (limit < 1 || limit > MAX_EVENTS_LIMIT) {
394	          badRequest(response, "limit must be a decimal integer between 1 and 100");
395	          return;
396	        }
397	      } else {
398	        cursorToken = raw;
399	      }
400	    }
401	
402	    if (fromIso !== null && toIso !== null && Date.parse(toIso) < Date.parse(fromIso)) {
403	      badRequest(response, "to must not be earlier than from");
404	      return;
405	    }
406	
407	    let cursor = null;
408	    if (cursorToken !== undefined) {
409	      cursor = decodeCursor(cursorToken);
410	      if (cursor === null) {
411	        badRequest(response, "cursor is invalid");
412	        return;
413	      }
414	      if (
415	        cursor.sid !== id
416	        || cursor.from !== fromIso
417	        || cursor.to !== toIso
418	        || cursor.limit !== limit
419	      ) {
420	        badRequest(response, "cursor does not match this query");
421	        return;
422	      }
423	      if (cursor.rev !== scenario.revision) {
424	        badRequest(response, "cursor is no longer valid because the scenario was modified");
425	        return;
426	      }
427	    }
428	
429	    const fromTime = fromIso === null ? null : Date.parse(fromIso);
430	    const toTime = toIso === null ? null : Date.parse(toIso);
431	    const afterSequence = cursor === null ? 0 : cursor.seq;
432	
433	    const page = [];
434	    let nextSequence = 0;
435	    for (const event of scenario.events) {
436	      if (event.sequence <= afterSequence) {
437	        continue;
438	      }
439	      const occurredAt = Date.parse(event.occurredAt);
440	      if (fromTime !== null && occurredAt < fromTime) {
441	        continue;
442	      }
443	      if (toTime !== null && occurredAt > toTime) {
444	        continue;
445	      }
446	      if (page.length === limit) {
447	        nextSequence = page[page.length - 1].sequence;
448	        break;
449	      }
450	      page.push(event);
451	    }
452	
453	    let nextCursor = null;
454	    if (nextSequence > 0) {
455	      nextCursor = encodeCursor({
456	        v: 1,
457	        sid: id,
458	        from: fromIso,
459	        to: toIso,
460	        limit,
461	        seq: nextSequence,
462	        rev: scenario.revision
463	      });
464	    }
465	
466	    sendJson(response, 200, {
467	      revision: scenario.revision,
468	      events: page,
469	      nextCursor
470	    });
471	  }
472	
473	  async function handleRequest(request, response) {
474	    const url = new URL(request.url ?? "/", "http://branchline.local");
475	    const segments = url.pathname.split("/");
476	
477	    try {
478	      if (request.method === "GET" && url.pathname === "/health") {
479	        sendJson(response, 200, {
480	          status: "ok",
481	          service: "branchline-core",
482	          version: "0.1.0"
483	        });
484	        return;
485	      }
486	
487	      if (segments.length === 2 && segments[1] === "scenarios") {
488	        if (request.method === "POST") {
489	          await createScenario(request, response);
490	          return;
491	        }
492	        if (request.method === "GET") {
493	          listScenarios(response);
494	          return;
495	        }
496	      } else if (segments.length === 3 && segments[1] === "scenarios") {
497	        const id = decodeURIComponent(segments[2]);
498	        if (request.method === "GET") {
499	          getScenario(response, id);
500	          return;
501	        }
502	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "branches") {
503	        const id = decodeURIComponent(segments[2]);
504	        if (request.method === "POST") {
505	          await createBranch(request, response, id);
506	          return;
507	        }
508	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "clock") {
509	        const id = decodeURIComponent(segments[2]);
510	        if (request.method === "POST") {
511	          await setClock(request, response, id);
512	          return;
513	        }
514	        if (request.method === "GET") {
515	          getClock(response, id);
516	          return;
517	        }
518	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "events") {
519	        const id = decodeURIComponent(segments[2]);
520	        if (request.method === "POST") {
521	          await appendEvent(request, response, id);
522	          return;
523	        }
524	        if (request.method === "GET") {
525	          listEvents(response, id, url);
526	          return;
527	        }
528	      }
529	
530	      notFound(response, "Route not found");
531	    } catch (error) {
532	      sendJson(response, 500, { error: "internal_error", message: "Internal server error" });
533	    }
534	  }
535	
536	  return { handleRequest };
537	}
538	
539	const defaultApp = createApp();
540	
541	export function handleRequest(request, response) {
542	  return defaultApp.handleRequest(request, response);
543	}
