314	  const id = randomUUID();
315	  const scenario = {
316	    id,
317	    name: "Seeded",
318	    description: "",
319	    revision: timestamps.length,
320	    createdAt: "2024-01-01T00:00:00.000Z",
321	    events: timestamps.map((occurredAt, index) => ({
322	      id: randomUUID(),
323	      type: `event-${index + 1}`,
324	      payload: { index },
325	      occurredAt,
326	      sequence: index + 1
327	    }))
328	  };
329	  store.scenarios.set(id, scenario);
330	  return { store, id, scenario, events: scenario.events };
331	}
